    public static class حنامينه
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "المرأه الجبلية لا تضرب الرجل، بل تقتله", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "فهم الناس يحلّ نصف المشكلة، يختصر المسافة", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "إن أكثرنا تطلباً للحب أكثرنا تطلباً للأمن، وأكثرنا حاجة للمرأة أكثرنا خوفاً من فقدانها", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "كل فنان سيظل يبحث حتى نهايه عمره، وهو مطالب خلال مسيره البحث هذه، بأن يجد الشكل الانسب لكل مضمون ملموس ولايكرر نفسه، مع المحافظة على شخصيته دون السقوط في التقليد..", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "من لايخطئ هو وحده الذي لايعمل", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "الغربة ليست وطنا، والصفصاف لا ينمو في الصحراء", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "فلا أحد يثور، أو يصبح ثائرا، في المعنى الكامل للكلمه، حين لا تكون له المقومات الاساسية، من شجاعه، وتجربه وثقافه، ومعرفه، أي دون أن يكون له مفهوم عن العالم", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "لا يمل التكرار، ولايخافه، حين يكون الموضوع متعلقا بقضيه مبدئيا أو انسانيه، يضع إصبعه في الثقب ويظل يبرمه حتى يفتح ثغره في الجدار، ويطمئن إلى أن الضوء صار يتدفق منها بشكل كاف لانارة كل جوانب القضيه المطروحة", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "لقد عشت في هذا العالم مايكفي كي لا أغدو ضيق الأفق وأنزلق إلى العدميه. أو كي لا أشاطر أفكار أحد من المحرفين. فَلَو حصل هذا لكان معاديا لمعتقداتي", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "القانون كي يحترم يجب أن يكون محترما في ذاته أي عادلا وكل احترام للقانون الظالم هو احترام للظلم استسلام له وهذا ليس من شيم المناضلين", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "وفي قاع الفلوكة مد البحارة أرجلهم واستراحوا. حين تنفرد الريح بالعزوف على الشراع لا بد أن يصمت المجذاف, وفي حال كهذه يحسن به أن يضع رأسه في الماء وينتحب وجداً كما تفعل الناعورة ذات الأنين. وقد انغمست رؤوس المجاذيف في الماء, وظلت مدلاة كذلك, فما دامت الريح قد واتت فلتسترح الاخشاب مشكورة على ما بذلت من جهد كبير لتعطي فائدة قليلة", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "الحياة حلوة. والموت حلو, كل شيء في وقته", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "لا يعرفون معنى الشرف،أو يتجاهلونه أو يحاولون القفز من فوق سوره العالي", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "صارت الان قطعة الخبز أعز ما في الوجود . صارت الوجود ذاته", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "كان سعيد حزوم يستلقي على الرمل الحار مستسلما بكل جوارحه إلى دفئه الذي ينعش قواه. كان يفتح عينيه ويغمضهما، ويشد بجسمه على الرمل كما لو أنه يود أن يغوص فيه. وقد قال في نفسه:\" وداعا أيها البحر\". قال أيضا:\" علي أن أودعه كبحّار. لقد انتهى كل شيء الآن. لم يعد الماء ملعبي ومملكتي. كابرت كثيرا، ورفضت تقبل هذه الحقيقة، وأصررت على أني لن أهرم، وسأظل ذلك البحار الذي كنته، لكن الأعوام، الأعوام الطويلة، أوهنت قواي، وصار علي منذ الآن، أن أقف على الشاطىء وأخوض في الماء بمقدار. سأسبح كما يفعل الآخرون، وقد أذهب في العمق قليلا، لكني لن أكون فارس البحر بعد اليوم. لقد ترجل الفارس وظلت الفرس شموسا. ظلت خطفا كأن قوائمها لا تلامس الأرض. لقد تعب البحار ولم يتعب البحر، وها هو كعهدي به يترقرق بموجه على الشاطىء، وديعاً، رفيقاً، حيياً، مختزناً قواه للشتاء، آن العواصف ثورة مدمرة تكتسح الحواجز، وتحطم المراكب، وتهزأ بالبحارة. وبانتظار ذلك يحيا البحر قانونه، ويجدد شبابه... البحر يجدد شبابه، والبحار يمضي إلى الشيخوخة.. آه، لماذا البحر يجدد شبابه والبحار يمضي إلى الشيخوخة؟", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = " إنني أتساءل بعد أن كبرت، لماذا ينشأ سوء التفاهم بين البشر بسبب تافه؟ لو أنهم ترووا قليلاً، وحاول كل طرف أن يتفهم وجهة نظر الطرف الآخر، لعاش الناس في محبة ووئام", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "أنا كاتب الكفاح والفرح الإنسانيين، فالكفاح له فرحه، له سعادته، له لذّته القصوى ، عندما تعرف أنك تمنح حياتك فداء لحياة الآخرين، هؤلاء الذين قد لا تعرف لبعضهم وجهاً، لكنك تؤمن في أعماقك، أن إنقاذهم من براثن الخوف والمرض والجوع والذل، جدير بأن يضحى في سبيله، ليس بالهناءة وحدها، بل بالمفاداة حتى الموت معها أيضاً.إن وعي الوجود عندي، ترافق مع تحويل التجربة إلى وعي، وكانت التجربة الأولى في حي (المستنقع) الذي نشأت فيه في اسكندرونة، مثل التجربة الأخيرة، حين أرحل عن هذه الدنيا ، ومثل تجربة الكفاح ما بينهما، منذورة كلها لمنح الرؤية للناس، لمساعدتهم على الخلاص من حمأة الجهل ، والسير بهم ومعهم نحو المعرفة، هذه التي هي الخطوة الأولى في (المسيرة الكبرى) نحو الغد الأفضل", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "مهنة الكاتب ليست سواراً من ذهب، بل هي أقصر طريق إلى التعاسة الكاملة. لا تفهموني خطأ، الحياة أعطتني، وبسخاء، يقال إنني أوسع الكتّاب العرب انتشاراً، مع نجيب محفوظ بعد نوبل ، ومع نزار قباني وغزلياته التي أعطته أن يكون عمر بن أبي ربيعة القرن العشرين. يطالبونني، في الوقت الحاضر، بمحاولاتي الأدبية الأولى، التي تنفع الباحثين والنقاد والدارسين، لكنها، بالنسبة إلي، ورقة خريف اسقطت مصابيح زرق", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "إن البحر كان دائماً مصدر إلهامي، حتى إن معظم أعمالي مبللة بمياه موجه الصاخب، وأسأل: هل قصدت ذلك متعمّدا؟ في الجواب أقول:في البدء لم أقصد شيئاً، لحمي سمك البحر، دمي ماؤه المالح، صراعي مع القروش كان صراع حياة،أما العواصف فقد نُقشت وشماً على جلدي، إذا نادوا: يا بحر أجبت أنا! البحر أنا، فيه وُلدت، وفيه أرغب أن أموت.. تعرفون معنى أن يكون المرء بحّاراً؟", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "إنه يتعمّد بماء اللجة لا بماء نهر الأردن، على طريقة يوحنا! أسألكم: أليس عجيباً، ونحن على شواطئ البحار،ألا نعرف البحر؟ ألا نكتب عنه؟ ألا نغامر والمغامرة احتجاج؟ أن يخلو أدبنا العربي، جديده والقديم، من صور هذا العالم الذي هو العالم، وما عداه، اليابسة، جزء منه؟! البحّار لا يصطاد من المقلاة! وكذلك لا يقعد على الشاطئ، بانتظار سمكة السردين التافهة. إنه أكبر، أكبر بكثير، وأنا هنا أتحدث عن البحّار لا عن فتى الميناء!", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "الأدباء العرب، أكثرهم لم يكتبوا عن البحر لأنهم خافوا معاينة الموت في جبهة الموج الصاخب. لا أدّعي الفروسية، المغامرة نعم! أجدادي بحّارة، هذه مهنتهم، الابن يتعلم حرفة أهله، احترفت العمل في الميناء كحمّال، واحترفت البحر كبحّار على المراكب. كان ذلك في الماضي الشقي والماجد من حياتي ، هذه المسيرة الطويلة كانت مشياً ، وبأقدام حافية، في حقول من مسامير، دمي سال في مواقع خطواتي، أنظر الآن إلى الماضي، نظرة تأمل حيادية، فأرتعش. كيف، كيف؟!", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "أين، أين؟! هناك البحر وأنا على اليابسة؟! أمنيتي الدائمة أن تنتقل دمشق إلى البحر، أو ينتقل البحر إلى دمشق، أليس هذا حلماً جميلاً؟! السبب أنني مربوط بسلك خفي إلى الغوطة ، ومشدود بقلادة ياسمين إلى ليالي دمشق الصيفية الفاتنة، وحارس مؤتمن على جبل قاسيون، ومغرم متيّم نهر بردى ، لذلك أحب فيروز والشاميات.", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = "المستحيل هو ما أردته أنت أن يكون مستحيلا", Author = "حنا مينه" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/حنا_مينه", Text = " كل أم ، وكل أخت ، وكل بنت في هذا الوطن هي أمنا وأختنا وبنتنا جميعا", Author = "حنا مينه" },
        };
    }
}